"""Compact append-only dependency storage and bounded reachability indexing."""

from __future__ import annotations

import array
import collections
from typing import final


@final
class Graph:
    """Store calculated dependencies without retaining transitive closure."""

    def __init__(self, cache_targets: int = 1024, cache_bytes: int = 64 * 1024**2):
        """Bound memoized expensive reachability questions independently of width."""
        self.offsets = array.array("Q", [0])
        self.edges = array.array("Q")
        self.heights = array.array("Q")
        self._first_consumer = array.array("q")
        self._next_consumer = array.array("q")
        self._consumers = array.array("Q")
        self._cache_targets = cache_targets
        self._cache_bytes = cache_bytes
        self._columns: collections.OrderedDict[int, bytearray] = (
            collections.OrderedDict()
        )
        self._column_bytes = 0
        self._expensive: collections.OrderedDict[int, int] = collections.OrderedDict()

    def __len__(self) -> int:
        """Count calculated operations."""
        return len(self.heights)

    def dependencies(self, operation: int) -> array.array[int]:
        """Read one operation's direct dependencies."""
        return self.edges[self.offsets[operation] : self.offsets[operation + 1]]

    def append(self, dependencies: list[int]) -> int:
        """Append an operation whose dependencies have already been calculated."""
        operation = len(self)
        height = 0
        for dependency in dependencies:
            dependency_height = self.heights[dependency] + 1
            if dependency_height > height:  # noqa: PLR1730 - Avoid a call per edge.
                height = dependency_height
            self._next_consumer.append(self._first_consumer[dependency])
            self._first_consumer[dependency] = len(self.edges)
            self._consumers.append(operation)
            self.edges.append(dependency)
        self.offsets.append(len(self.edges))
        self.heights.append(height)
        self._first_consumer.append(-1)
        return operation

    def _column(self, previous: int, following: int) -> bytearray:
        column = self._columns.pop(previous, bytearray())
        self._column_bytes -= len(column)
        required = max(len(column), following - previous + 1)
        while self._columns and (
            self._column_bytes + required > self._cache_bytes
            or len(self._columns) >= self._cache_targets
        ):
            _, removed = self._columns.popitem(last=False)
            self._column_bytes -= len(removed)
        column.extend(bytes(required - len(column)))
        column[0] = 2
        self._columns[previous] = column
        self._column_bytes += len(column)
        return column

    def _memoized_reaches(
        self, following: int, previous: int, column: bytearray
    ) -> bool:
        pending = [(following, self.offsets[following])]
        minimum_height = self.heights[previous]
        while pending:
            current, offset = pending[-1]
            if column[current - previous]:
                _ = pending.pop()
            elif offset == self.offsets[current + 1]:
                column[current - previous] = 1
            else:
                dependency = self.edges[offset]
                if dependency < previous:
                    pending[-1] = (current, offset + 1)
                elif column[dependency - previous] == 2:
                    column[current - previous] = 2
                elif (
                    column[dependency - previous] == 0
                    and self.heights[dependency] > minimum_height
                ):
                    pending.append((dependency, self.offsets[dependency]))
                else:
                    pending[-1] = (current, offset + 1)
        return column[following - previous] == 2

    def _repeated_expensive(self, previous: int) -> bool:
        count = self._expensive.pop(previous, 0) + 1
        if count >= 3:
            return True
        self._expensive[previous] = count
        if len(self._expensive) > 1024:
            _ = self._expensive.popitem(last=False)
        return False

    def reaches(self, following: int, previous: int) -> bool:
        """Test strict dependency reachability in the calculated graph."""
        if following <= previous or self.heights[following] <= self.heights[previous]:
            return False
        if self._first_consumer[previous] < 0:
            return False
        if previous in self._columns and following - previous < self._cache_bytes:
            return self._memoized_reaches(
                following, previous, self._column(previous, following)
            )
        backward = collections.deque([(following, self.offsets[following])])
        forward = collections.deque([(previous, self._first_consumer[previous])])
        earlier_seen = {following}
        later_seen = {previous}
        minimum_height = self.heights[previous]
        maximum_height = self.heights[following]
        consider_cache = (
            self._cache_targets > 0 and following - previous < self._cache_bytes
        )
        shared: int | None = None
        while backward and forward:
            if consider_cache and len(earlier_seen) + len(later_seen) >= 64:
                if (
                    shared is not None
                    and self._repeated_expensive(shared)
                    and self._memoized_reaches(
                        following, shared, self._column(shared, following)
                    )
                ):
                    return True
                if self._repeated_expensive(previous):
                    return self._memoized_reaches(
                        following, previous, self._column(previous, following)
                    )
                consider_cache = False
            current, offset = backward[0]
            if offset == self.offsets[current + 1]:
                _ = backward.popleft()
            else:
                dependency = self.edges[offset]
                backward[0] = (current, offset + 1)
                if dependency in later_seen:
                    return True
                if (
                    self.heights[dependency] > minimum_height
                    and dependency > previous
                    and dependency not in earlier_seen
                ):
                    earlier_seen.add(dependency)
                    backward.append((dependency, self.offsets[dependency]))
            current, offset = forward[0]
            if offset < 0:
                _ = forward.popleft()
            else:
                consumer = self._consumers[offset]
                forward[0] = (current, self._next_consumer[offset])
                if consumer in earlier_seen:
                    return True
                if (
                    self.heights[consumer] < maximum_height
                    and consumer < following
                    and consumer not in later_seen
                ):
                    later_seen.add(consumer)
                    if (
                        consumer in self._columns
                        and following - consumer < self._cache_bytes
                    ):
                        if self._memoized_reaches(
                            following, consumer, self._column(consumer, following)
                        ):
                            return True
                    else:
                        if (
                            consider_cache
                            and shared is None
                            and self.offsets[consumer + 1] - self.offsets[consumer] > 1
                        ):
                            shared = consumer
                        forward.append((consumer, self._first_consumer[consumer]))
        return False

supporting.state_workloads.py:
"""State-driven valid operations, independent of dependency graph construction."""

from __future__ import annotations

import dataclasses
import random
from typing import cast, final

from operation_graph_optimization import algorithm


class Positions:
    """A collection with constant-time indexed selection and removal."""

    def __init__(self):
        """Start with no eligible positions."""
        self.values: list[int] = []
        self.indexes: dict[int, int] = {}

    def add(self, position: int):
        """Include a newly eligible position."""
        self.indexes[position] = len(self.values)
        self.values.append(position)

    def remove(self, position: int):
        """Remove a position that is no longer eligible."""
        index = self.indexes.pop(position)
        last = self.values.pop()
        if index < len(self.values):
            self.values[index] = last
            self.indexes[last] = index


@dataclasses.dataclass(slots=True)
class Position:
    """A position defined by a particular particle, or by the current action."""

    rank: int
    owner: int | None
    name: str
    particle: int | None = None


@dataclasses.dataclass(slots=True)
class Particle:
    """An existing particle and the positions it defines."""

    position: int
    children: tuple[int, ...]


@dataclasses.dataclass(frozen=True, slots=True)
class Choice:
    """One valid statement's final position or source and destination."""

    source: int | None = None
    destination: int | None = None


@final
class State:
    """Track occupancy and particle identity without consulting operation edges."""

    def __init__(self, width: int, depth: int, branching: int, access: str = "local"):
        """Start with empty local positions of each supported constraint shape."""
        self.branching = branching
        self.access = access
        self.positions: dict[int, Position] = {}
        self.particles: dict[int, Particle] = {}
        self.empty = [Positions() for _ in range(depth + 1)]
        self.occupied = [Positions() for _ in range(depth + 1)]
        self.next_position = 0
        self.occurrence = 0
        for rank in range(depth + 1):
            for index in range(width):
                prefix = "/" if access == "implied" else ""
                _ = self._position(rank, None, f"position<{prefix}p{rank}_{index}>")
        self.initial: list[algorithm.Operation] = []
        if access == "implied":
            # The action's own particle exists before its implied qualities
            # can be accessed; it is not one of the movable test particles.
            self.initial.append(
                algorithm.Operation(fill=-1, defines=tuple(self.positions))
            )
            self.occurrence = 1

    def _position(self, rank: int, owner: int | None, name: str) -> int:
        position = self.next_position
        self.next_position += 1
        self.positions[position] = Position(rank, owner, name)
        self.empty[rank].add(position)
        return position

    def counts(self) -> tuple[int, int, int]:
        """Count valid Creates, Moves, and Destroy statements."""
        creates = moves = destroys = 0
        for empty, occupied in zip(self.empty, self.occupied, strict=True):
            creates += len(empty.values)
            moves += len(empty.values) * len(occupied.values)
            destroys += len(occupied.values)
        return creates, moves, destroys

    def choice(self, kind: int, ticket: int) -> Choice:
        """Select one statement by its index among all choices of its kind."""
        for empty, occupied in zip(self.empty, self.occupied, strict=True):
            if kind == 0:
                count = len(empty.values)
            elif kind == 1:
                count = len(empty.values) * len(occupied.values)
            else:
                count = len(occupied.values)
            if ticket >= count:
                ticket -= count
                continue
            if kind == 0:
                return Choice(destination=empty.values[ticket])
            if kind == 2:
                return Choice(source=occupied.values[ticket])
            source, destination = divmod(ticket, len(empty.values))
            return Choice(occupied.values[source], empty.values[destination])
        raise IndexError("Choice ticket is outside the valid operation collection")

    def sample(self, randomizer: random.Random, distribution: str) -> Choice:
        """Choose without favoring collection insertion order."""
        counts = self.counts()
        if distribution == "concrete":
            weights = counts
        else:
            preferences = {
                "balanced": (1, 1, 1),
                "growth": (8, 4, 1),
                "movement": (1, 12, 1),
                "destruction": (4, 1, 4),
            }[distribution]
            weights = tuple(
                preference if count else 0
                for preference, count in zip(preferences, counts, strict=True)
            )
        ticket = randomizer.randrange(sum(weights))
        for kind, weight in enumerate(weights):
            if ticket < weight:
                return self.choice(kind, randomizer.randrange(counts[kind]))
            ticket -= weight
        raise AssertionError("A weighted choice must select an operation kind")

    def reference(self, position: int) -> tuple[str, tuple[int, ...], tuple[int, ...]]:
        """Resolve the written reference using the particles' current positions."""
        names: list[str] = []
        occupied: list[int] = []
        creators: list[int] = []
        current = position
        while True:
            state = self.positions[current]
            names.append(state.name)
            if state.owner is None:
                if self.access == "implied":
                    creators.append(0)
                break
            creators.append(state.owner)
            current = self.particles[state.owner].position
            occupied.append(current)
        return "::".join(reversed(names)), tuple(occupied), tuple(creators)

    def statement(self, choice: Choice) -> str:
        """Render a choice before applying its effects."""
        if choice.source is None:
            destination = cast("int", choice.destination)
            return f"create a particle in {self.reference(destination)[0]}."
        source = self.reference(choice.source)[0]
        if choice.destination is None:
            return f"destroy the particle in {source}."
        destination = self.reference(choice.destination)[0]
        return f"move the particle in {source} to {destination}."

    def apply(self, choice: Choice) -> list[algorithm.Operation]:
        """Apply one statement, selecting all simultaneous Destroys together."""
        occupied: list[int] = []
        creators: list[int] = []
        for position in (choice.source, choice.destination):
            if position is not None:
                _, required, owners = self.reference(position)
                # Move references can share intermediate positions and particles.
                for intermediate in required:
                    if intermediate not in occupied:
                        occupied.append(intermediate)
                for owner in owners:
                    if owner not in creators:
                        creators.append(owner)
        if choice.source is None:
            destination_position = cast("int", choice.destination)
            destination = self.positions[destination_position]
            children: list[int] = []
            if destination.rank:
                for index in range(self.branching):
                    children.append(
                        self._position(
                            destination.rank - 1,
                            self.occurrence,
                            f"position</child{destination.rank}_{index}>",
                        )
                    )
            particle = self.occurrence
            self.particles[particle] = Particle(destination_position, tuple(children))
            self._fill(destination_position, particle)
            operations = [
                algorithm.Operation(
                    occupied=tuple(occupied),
                    fill=choice.destination,
                    creators=tuple(creators),
                    defines=tuple(children),
                )
            ]
            # Each rank's constructor performs this local work. These are real
            # callee statements, not sampler-imposed follow-up choices.
            temporary = self.next_position
            self.next_position += 1
            operations.extend(
                [
                    algorithm.Operation(fill=temporary),
                    algorithm.Operation(empty=temporary),
                ]
            )
        elif choice.destination is not None:
            particle = self._empty(choice.source)
            self._fill(choice.destination, particle)
            self.particles[particle].position = choice.destination
            operations = [
                algorithm.Operation(
                    occupied=tuple(occupied),
                    empty=choice.source,
                    fill=choice.destination,
                    creators=tuple(creators),
                )
            ]
        else:
            operations = [
                algorithm.Operation(
                    occupied=tuple(occupied),
                    empty=choice.source,
                    creators=tuple(creators),
                )
            ]
            pending = [choice.source]
            removed: list[int] = []
            while pending:
                position = pending.pop()
                particle = self._empty(position)
                for child in self.particles.pop(particle).children:
                    removed.append(child)
                    if self.positions[child].particle is not None:
                        pending.append(child)
                        operations.append(algorithm.Operation(empty=child))
            for child in removed:
                self.empty[self.positions[child].rank].remove(child)
                del self.positions[child]
        self.occurrence += len(operations)
        return operations

    def _empty(self, position: int) -> int:
        state = self.positions[position]
        particle = cast("int", state.particle)
        state.particle = None
        self.occupied[state.rank].remove(position)
        self.empty[state.rank].add(position)
        return particle

    def _fill(self, position: int, particle: int):
        state = self.positions[position]
        self.empty[state.rank].remove(position)
        self.occupied[state.rank].add(position)
        state.particle = particle


def generate(
    seed: int,
    steps: int,
    width: int,
    depth: int,
    branching: int,
    distribution: str,
    access: str = "local",
) -> tuple[list[algorithm.Operation], dict[int, int]]:
    """Generate mixed statements and mark simultaneous Destroy groups."""
    state = State(width, depth, branching, access)
    randomizer = random.Random(seed)  # noqa: S311 - Reproducible workloads.
    operations = list(state.initial)
    groups: dict[int, int] = {}
    for _ in range(steps):
        choice = state.sample(randomizer, distribution)
        batch = state.apply(choice)
        if choice.destination is None and len(batch) > 1:
            groups[len(operations)] = len(batch)
        operations.extend(batch)
    return operations, groups

supporting.order_variants.py:
"""Valid statement reorderings from an independent, unreduced conflict graph."""

from __future__ import annotations

import dataclasses
import random
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from operation_graph_optimization import algorithm


def reorder(
    operations: list[algorithm.Operation],
    groups: dict[int, int],
    seed: int,
) -> tuple[list[algorithm.Operation], dict[int, int], list[int]]:
    """Randomize ready statements without using the rule algorithm's graph."""
    starts: list[int] = []
    statement_for: list[int] = []
    occurrence = 0
    while occurrence < len(operations):
        count = groups.get(occurrence, 1)
        statement_for.extend([len(starts)] * count)
        starts.append(occurrence)
        occurrence += count

    changed: dict[int, int] = {}
    used: dict[int, set[int]] = {}
    consumers: list[list[int]] = [[] for _ in starts]
    remaining: list[int] = []
    for statement, start in enumerate(starts):
        count = groups.get(start, 1)
        dependencies: set[int] = set()
        for operation in operations[start : start + count]:
            dependencies.update(
                statement_for[creator] for creator in operation.creators
            )
            for position in (*operation.occupied, operation.fill, operation.empty):
                if position is not None and position in changed:
                    dependencies.add(changed[position])
            if operation.empty is not None:
                dependencies.update(used.get(operation.empty, ()))
        remaining.append(len(dependencies))
        for dependency in dependencies:
            consumers[dependency].append(statement)
        # A simultaneous group observes one preceding state, not its peers.
        for operation in operations[start : start + count]:
            for position in operation.occupied:
                used.setdefault(position, set()).add(statement)
            for position in (operation.fill, operation.empty, *operation.defines):
                if position is not None:
                    changed[position] = statement
                    _ = used.pop(position, None)

    randomizer = random.Random(seed)  # noqa: S311 - Reproducible valid source orders.
    ready = [statement for statement, count in enumerate(remaining) if count == 0]
    ordered: list[int] = []
    reordered_groups: dict[int, int] = {}
    while ready:
        index = randomizer.randrange(len(ready))
        statement = ready[index]
        ready[index] = ready[-1]
        _ = ready.pop()
        start = starts[statement]
        count = groups.get(start, 1)
        if count > 1:
            reordered_groups[len(ordered)] = count
        ordered.extend(range(start, start + count))
        for consumer in consumers[statement]:
            remaining[consumer] -= 1
            if remaining[consumer] == 0:
                ready.append(consumer)
    if len(ordered) != len(operations):
        raise ValueError("The independent statement dependencies contain a cycle")
    new_occurrence = [0] * len(operations)
    for current, original in enumerate(ordered):
        new_occurrence[original] = current
    reordered: list[algorithm.Operation] = []
    for original in ordered:
        operation = operations[original]
        reordered.append(
            dataclasses.replace(
                operation,
                creators=tuple(
                    new_occurrence[creator] for creator in operation.creators
                ),
            )
        )
    return reordered, reordered_groups, ordered

