"""Replay the archived comparison without editing the live algorithm."""
import argparse
import gc
import hashlib
import json
import pathlib
import statistics
import sys
import time
import types

from operation_graph_optimization import order_variants, state_workloads, validation, workloads

parser = argparse.ArgumentParser()
parser.add_argument("--artifact", default="operation_graph_optimization/collection_results.json")
parser.add_argument("--phase", choices=["screen", "large", "confirmation"])
parser.add_argument("--smoke", action="store_true")
args = parser.parse_args()
artifact = json.loads(pathlib.Path(args.artifact).read_text())
for name, source in artifact["sources"]["supporting"].items():
    actual = pathlib.Path("operation_graph_optimization", name).read_text()
    if actual != source:
        raise ValueError(f"Supporting source changed: {name}; use the archived version in a separate checkout")
factories = {}
for label in ("baseline", "skip"):
    module = types.ModuleType(f"archived_collection_{label}")
    sys.modules[module.__name__] = module
    source = artifact["sources"][f"{label}_algorithm"]
    exec(compile(source, f"<{module.__name__}>", "exec"), module.__dict__)
    factories[label] = module.Calculator
    print(json.dumps({"implementation": label, "sha256": hashlib.sha256(source.encode()).hexdigest()}), flush=True)

def construct(factory, operations, groups):
    wall_start = time.perf_counter()
    cpu_start = time.process_time()
    calculator = factory()
    occurrence = 0
    while occurrence < len(operations):
        count = groups.get(occurrence, 1)
        if count > 1:
            calculator.simultaneous(operations[occurrence:occurrence + count])
        else:
            calculator.add(operations[occurrence])
        occurrence += count
    cpu_elapsed = time.process_time() - cpu_start
    wall_elapsed = time.perf_counter() - wall_start
    return calculator.graph, wall_elapsed, cpu_elapsed

for record in artifact["records"]:
    if args.phase and args.phase != record["phase"]:
        continue
    steps = 40 if args.smoke else record["steps"]
    name = record["workload"]
    if name == "shared":
        operations, groups = list(workloads.shared_parent(record["seed"], steps, record["width"])), {}
    elif name == "implied":
        operations, groups = list(workloads.implied_uses(record["seed"], steps, record["width"])), {}
    else:
        distribution = "growth" if name == "growth_reordered" else name
        operations, groups = state_workloads.generate(
            record["seed"], steps, record["width"], record["depth"],
            record["branching"], distribution, record["access"],
        )
        if record["reorder_seed"] is not None:
            operations, groups, _ = order_variants.reorder(operations, groups, record["reorder_seed"])
    if not args.smoke:
        assert len(operations) == record["operations"]
    expected, _, _ = construct(factories["baseline"], operations, groups)
    if record["random_schedule_seed"] is not None:
        validation.check_random_schedule(operations, expected, record["random_schedule_seed"])
    measured = {"baseline": [], "skip": []}
    repetitions = 1 if args.smoke else len(record["baseline_wall_seconds"])
    for repetition in range(repetitions + 1):
        order = ["baseline", "skip"]
        if repetition % 2:
            order.reverse()
        for label in order:
            gc.collect()
            result, wall, cpu = construct(factories[label], operations, groups)
            assert result.offsets == expected.offsets
            for occurrence in range(len(operations)):
                assert set(result.dependencies(occurrence)) == set(expected.dependencies(occurrence))
            if repetition:
                measured[label].append({"wall_seconds": wall, "cpu_seconds": cpu})
            del result
    print(json.dumps({
        "phase": record["phase"], "workload": name, "seed": record["seed"],
        "depth": record["depth"], "operations": len(operations),
        "smoke": args.smoke, "graphs_equal": True, "measurements": measured,
    }), flush=True)
    del expected, operations, groups
